    "desc": "统计期内线缆-中压电缆-交联实际合格品完工产量。现场技术接入规则：接口对接；借道经营日报管理系统（报管系统）数据中继网关，穿透抽取特变电工股份大数据平台中线缆该产线的实际完工产量，日更新免人工填报；作为对应工序单耗指标的核心分母。",
